#include <deque>
#include <iostream>
#include <random>

struct Cell
{
    int x{}, y{};
    bool operator==(const Cell&) const = default;
};

class Snake
{
public:
    void tick() {}
    bool over() const { return m_over; }

private:
    std::deque<Cell> m_body{{5, 7}, {4, 7}, {3, 7}};
    Cell m_dir{1, 0};
    Cell m_food{10, 7};
    bool m_over{false};
    std::mt19937 m_rng{3};
};

int main()
{
    Snake s{};
    s.tick();
}
